/** Generated files for the agent lane: constants the Go CLI shares with the service, and (see
 * `agentKitOutputs`) the runbook and guide the CLI embeds for `rastrata agent init`.
 *
 * Everything here is derived from one source in this repository, so the CLI, the service, the web
 * app and the MCP server never disagree: the token rules in packages/application/src/agent, and the
 * guide in plugins/rastrata. `generate-application-contracts.ts` writes these files and `--check`
 * fails when one is stale. */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { loadBookkeepingSkill } from "../apps/mcp/src/skill.ts";
import {
  DEFAULT_TOKEN_DAYS,
  GRANTABLE_PERMISSIONS,
  MAX_LABEL_LENGTH,
  MAX_TOKEN_DAYS,
  TOKEN_PRESETS,
} from "../packages/application/src/agent/token.ts";

export const root = resolve(import.meta.dir, "..");

/** gofmt is deterministic, so the committed file is exactly what the generator writes. */
function gofmt(source: string): string {
  const run = Bun.spawnSync([process.env.GOFMT_BIN ?? "gofmt"], {
    stdin: Buffer.from(source),
    stdout: "pipe",
    stderr: "pipe",
  });
  if (run.exitCode !== 0) throw new Error(new TextDecoder().decode(run.stderr));
  return new TextDecoder().decode(run.stdout);
}

const quoted = (values: readonly string[]) =>
  values.map((value) => JSON.stringify(value)).join(", ");

function constants(): string {
  const presets = Object.entries(TOKEN_PRESETS)
    .map(([name, permissions]) => `\t${JSON.stringify(name)}: {${quoted(permissions)}},`)
    .join("\n");
  return gofmt(`// Code generated by scripts/agent-kit.ts; DO NOT EDIT.

package agentkit

// GrantablePermissions are the permissions an agent token may hold, in canonical order. A token
// never holds provision.
var GrantablePermissions = []string{${quoted(GRANTABLE_PERMISSIONS)}}

// TokenPresets name the usual choices of access for an agent.
var TokenPresets = map[string][]string{
${presets}
}

const (
	// DefaultTokenDays is how long a token lasts when the owner does not choose.
	DefaultTokenDays = ${DEFAULT_TOKEN_DAYS}
	// MaxTokenDays is the longest a token may last.
	MaxTokenDays = ${MAX_TOKEN_DAYS}
	// MaxLabelLength is the longest label a token may have.
	MaxLabelLength = ${MAX_LABEL_LENGTH}
)
`);
}

const SKILL_FILE = "plugins/rastrata/skills/bookkeeping/SKILL.md";

/** The runbook: the agent lane's block of the bookkeeping skill, between its markers. It is the
 * single source of the weekly routine for the MCP guide and for every file `agent init` writes. */
function runbook(): string {
  const text = readFileSync(resolve(root, SKILL_FILE), "utf8");
  const match = /<!-- agent lane: begin[^\n]*-->\n([\s\S]*?)<!-- agent lane: end -->/.exec(text);
  if (!match?.[1]) throw new Error(`${SKILL_FILE} has no agent lane block between its markers`);
  return `${match[1].trim()}\n`;
}

/** The full guide for the command line: the same text the MCP server serves (with its tool table),
 * minus the skill frontmatter, with a note for readers who use commands rather than tools. */
function guide(): string {
  const body = loadBookkeepingSkill()
    .text.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/, "")
    .trimStart();
  return `> This guide is shared with the MCP server, so it names tools such as \`rastrata_get_book\`. On the command line, find the tool in the table at the end and run its operation: \`rastrata call book.get --input -\`, or a shorter command from \`rastrata help\` (for example \`rastrata context\`).\n\n${body}`;
}

/** Every generated file of the agent lane, by path relative to the repository root. */
export function agentKitOutputs(): Map<string, string> {
  return new Map([
    ["apps/terminal/internal/agentkit/constants_gen.go", constants()],
    ["apps/terminal/internal/agentkit/kit/runbook.md", runbook()],
    ["apps/terminal/internal/agentkit/kit/guide.md", guide()],
  ]);
}
